const token = $input.first().headers['x-webhook-token'];
const expected = process.env.N8N_WEBHOOK_TOKEN || '';
if (!expected) {
  // No token configured — warn but allow through in dev
  console.warn('WARNING: N8N_WEBHOOK_TOKEN not set. Allowing request through.');
  return $input.all();
}
if (token !== expected) {
  throw new Error('Unauthorized: invalid webhook token');
}
return $input.all();

const data = $input.first().json;
const templates = (data.templates || data || []).map(t => ({
  id: t.id,
  name: t.name,
  type: t.type,
  subject: t.subject || '',
  html: t.html || t.body || '',
  updatedAt: t.updatedAt || t.dateUpdated || ''
}));

return [{ json: { templates, count: templates.length } }];

const content = $input.first().json;
const jsonStr = JSON.stringify(content, null, 2);
const base64 = Buffer.from(jsonStr).toString('base64');
return [{
  json: {},
  binary: {
    data: {
      data: base64,
      mimeType: 'application/json',
      fileName: 'ghl_templates.json'
    }
  }
}];
